// 200 services, 10k req/s -> daily request volume
const reqPerSec = 10000;
const reqPerDay = reqPerSec * 86400; // 864M req/day

// telemetry generated per signal (GB/day, untuned)
const gbPerDay = { logs: 4000, metrics: 2500, traces: 2500, profiles: 1000 };
const pricePerGB = 0.50; // ingest+storage blended $/GB

function bill(v) {
  return Object.values(v).reduce((s, gb) => s + gb * pricePerGB, 0) * 365;
}

const untuned = bill(gbPerDay);
console.log('Untuned annual bill: $' + Math.round(untuned).toLocaleString());
console.log('Cost per million requests: $' + ((untuned / 365) / (reqPerDay / 1e6)).toFixed(2));

// apply the three levers
const tuned = {
  logs:     gbPerDay.logs * 0.60,    // tiered retention + level audit -> -40%
  metrics:  gbPerDay.metrics * 0.50, // cardinality limits -> -50%
  traces:   gbPerDay.traces * 0.15,  // tail sampling keeps errors/slow + 5% -> -85%
  profiles: gbPerDay.profiles * 1.0  // leave profiles (~10% of bill)
};

const tunedBill = bill(tuned);
const saved = untuned - tunedBill;
console.log('Tuned annual bill: $' + Math.round(tunedBill).toLocaleString());
console.log('Saved: $' + Math.round(saved).toLocaleString() + ' (' + Math.round(saved / untuned * 100) + '%)');
console.log('Tuned cost per million requests: $' + ((tunedBill / 365) / (reqPerDay / 1e6)).toFixed(2));
